<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {createMaterialEnhancementApi} from './material-enhancement-api';import {useMaterialEnhancement} from './useMaterialEnhancement';
const props=defineProps<{meetingId:string;allowed:boolean;active:boolean}>(),emit=defineEmits<{adopted:[];pending:[value:boolean]}>(),app=useApplication();
const controller=useMaterialEnhancement(createMaterialEnhancementApi(app.session.client,()=>app.session.current.value?.actor.enterpriseId??null),{context:app.journals,actor:()=>app.session.current.value?.actor.enterpriseId??null,meeting:()=>props.meetingId,canMutate:()=>props.allowed&&props.active,current:()=>app.transcripts.current(props.meetingId,new AbortController().signal),materials:()=>app.materials.list(props.meetingId,new AbortController().signal),adopted:()=>{emit('adopted');}});
watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId],()=>controller.synchronize(),{immediate:true,flush:'sync'});watch(()=>controller.pending.value,value=>emit('pending',value),{immediate:true});onUnmounted(()=>controller.dispose());
const panel=ref<HTMLDetailsElement>();
function show(){if(panel.value){panel.value.open=true;panel.value.querySelector('summary')?.focus();}}
defineExpose({pending:controller.pending,show});
</script>
<template><details ref="panel" class="material-enhancement"><summary>根据背景材料增强转写</summary><p class="small muted">基于已保存稿件和当前已解析材料生成候选。核对后采用将创建新版本，原始转写与历史稿保留。</p><p v-if="controller.error.value" class="ac-error" role="alert">{{controller.error.value}}</p><p v-if="!allowed" class="small muted">请先保存当前修改并完成其他待恢复操作。</p><button v-if="!controller.intent.value" type="button" class="btn" :disabled="!allowed||controller.busy.value||controller.storageBlocked.value" @click="controller.start">生成增强候选</button><button v-else type="button" class="btn" :disabled="controller.busy.value" @click="controller.retry">{{controller.pending.value?'恢复原增强操作':'核对候选与材料版本'}}</button><template v-if="controller.view.value"><p v-if="controller.view.value.state==='STALE'" role="status">原稿或背景材料已变化，请重新生成候选。</p><p v-else-if="controller.view.value.state==='PENDING'" role="status">候选生成尚未完成，请恢复原请求。</p><p v-else-if="controller.view.value.state==='APPLIED'" role="status">候选已经采用，请读取最新工作稿。</p><template v-else-if="controller.view.value.state==='READY'"><p v-if="controller.view.value.materialRefresh&&!controller.view.value.changes.length" role="status">正文没有改动，采用候选可更新使用的材料版本。</p><p v-else-if="!controller.view.value.changes.length" role="status">未发现需要替换的内容，当前稿件保持不变。</p><div v-for="change in controller.view.value.changes" :key="change.segmentId" class="enhancement-change"><div><b>当前稿</b><p>{{change.before}}</p></div><div><b>增强候选</b><p>{{change.after}}</p></div></div><button v-if="controller.view.value.canApply" type="button" class="btn primary" :disabled="!allowed||controller.busy.value" @click="controller.adopt">采用候选并保存为新版本</button></template></template><button v-if="controller.intent.value&&!controller.pending.value" type="button" class="btn ghost" :disabled="controller.busy.value" @click="controller.discard">{{controller.view.value?.state==='STALE'?'清除旧候选，重新生成':'保留当前稿，关闭候选'}}</button></details></template>
<style scoped>.material-enhancement{border:1px solid var(--border);border-radius:10px;padding:12px;margin:12px 0}.material-enhancement summary{cursor:pointer;font-weight:600}.material-enhancement>.btn{margin:8px 8px 0 0}.enhancement-change{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:12px 0;padding:12px;background:var(--bg)}.enhancement-change p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}</style>
